import{_ as l,o as a,c as o,aw as n}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Repaint & Reflow","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/critical-rendering-path/rendering/repaint-and-reflow.md","filePath":"wiki/dev-commit/js/critical-rendering-path/rendering/repaint-and-reflow.md"}'),t={name:"wiki/dev-commit/js/critical-rendering-path/rendering/repaint-and-reflow.md"};function e(p,s,r,i,c,y){return a(),o("div",null,[...s[0]||(s[0]=[n(`<h1 id="repaint-reflow" tabindex="-1">Repaint &amp; Reflow <a class="header-anchor" href="#repaint-reflow" aria-label="Permalink to &quot;Repaint &amp; Reflow&quot;">​</a></h1><ul><li><strong>Repaint</strong> и <strong>Reflow</strong> блокируют браузер и не пользователь, и не ваше веб-приложение не смогут ничего сделать во время reflow и repaint. В крайних случаях CSS эффекты могут затормозить выполнение JavaScript&#39;а. Это одна из причин, почему вы сталкиваетесь с дергающейся прокруткой страницы и неотзывчивым интерфейсом</li></ul><h2 id="repaint-restyle" tabindex="-1">Repaint (Restyle) <a class="header-anchor" href="#repaint-restyle" aria-label="Permalink to &quot;Repaint (Restyle)&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Repaint</strong> (Перерисовка) - в случае изменения стилей элемента, не влияющих на его размеры и положение на странице: background-color, border-color, visibility, opacity, outline и т.д.</li></ul></div><ul><li>Браузер просто отрисовывает его заново, с учётом нового стиля</li></ul><h2 id="reflow-relayout" tabindex="-1">Reflow (Relayout) <a class="header-anchor" href="#reflow-relayout" aria-label="Permalink to &quot;Reflow (Relayout)&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Reflow</strong> (Перекомпановка) - если изменения затрагивают содержимое, структуру документа, положение элементов, происходит перерасчет позиций и размеров всех элементов, что приводит к полной или частичной повторной отрисовке страницы</li></ul></div><ul><li>Изменения в одном элементе могут повлиять на все дочерние, родительские или смежные элементы</li></ul><p><strong>Когда запускается reflow</strong></p><ul><li>Манипуляции с DOM (добавление, удаление, изменение, перестановка ВИДИМЫХ элементов)</li><li>Расчёт или изменение CSS-свойств (н-р: изменив ширину элемента, вы можете повлиять на все элементы того же уровня в DOM и окружающие его элементы)</li><li>Добавление, удаление таблиц стилей</li><li>Манипуляции с атрибутом «class»</li><li>CSS3 анимация и свойство transition (каждый кадр анимации вызывает reflow)</li><li>Использование offsetWidth и OffsetHeight (при попытке считать значения offsetWidth и offsetHeight элемента для их вычисления может быть запущен reflow)</li></ul><p><strong>Действия пользователя</strong></p><ul><li>Изменение содержимого, в т.ч. текста в полях форм</li><li>Манипуляции с окном браузера - изменения размеров, прокрутка</li><li>Активация псевдо-классов (например, :hover)</li><li>Изменении размера шрифта</li></ul><h2 id="оптимизация-со-стороны-браузера" tabindex="-1">Оптимизация со стороны браузера <a class="header-anchor" href="#оптимизация-со-стороны-браузера" aria-label="Permalink to &quot;Оптимизация со стороны браузера&quot;">​</a></h2><ol><li>Браузеры по возможности локализуют repaint и reflow в пределах элементов, подвергнувшимися изменению. Например, изменение размеров абсолютно или <em>фиксировано</em> спозиционированного элемента затронет только сам элемент и его потомков, в то время как изменение статично спозиционированного - повлечет <em>reflow</em> всех элементов, следующих за ним</li><li>Во время выполнения JavaScript браузеры кэшируют вносимые изменения, и применяют их в один проход по завершению работы блока кода</li></ol><ul><li>В ходе выполнения данного кода произойдет только один reflow и repaint:</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> $body</span><span style="color:#0184BC;"> =</span><span style="color:#4078F2;"> $</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;body&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;padding&quot;</span><span style="color:#383A42;">, </span><span style="color:#50A14F;">&quot;1px&quot;</span><span style="color:#383A42;">); </span><span style="color:#A0A1A7;font-style:italic;">// reflow, repaint</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;color&quot;</span><span style="color:#383A42;">, </span><span style="color:#50A14F;">&quot;red&quot;</span><span style="color:#383A42;">); </span><span style="color:#A0A1A7;font-style:italic;">// repaint</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;margin&quot;</span><span style="color:#383A42;">, </span><span style="color:#50A14F;">&quot;2px&quot;</span><span style="color:#383A42;">); </span><span style="color:#A0A1A7;font-style:italic;">// reflow, repaint</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// На самом деле произойдет только 1 reflow и repaint</span></span></code></pre></div><ul><li>Но, как описано выше, обращение к свойствам элементов вызовет принудительный reflow. То есть, если мы в приведённый блок кода добавим обращение к свойству элемента, это вызовет лишний reflow:</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> $body</span><span style="color:#0184BC;"> =</span><span style="color:#4078F2;"> $</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;body&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;padding&quot;</span><span style="color:#383A42;">, </span><span style="color:#50A14F;">&quot;1px&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// обращение к свойству, принудительный reflow</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;padding&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;color&quot;</span><span style="color:#383A42;">, </span><span style="color:#50A14F;">&quot;red&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">$body.</span><span style="color:#4078F2;">css</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;margin&quot;</span><span style="color:#383A42;">, </span><span style="color:#50A14F;">&quot;2px&quot;</span><span style="color:#383A42;">);</span></span></code></pre></div>`,18)])])}const A=l(t,[["render",e]]);export{u as __pageData,A as default};
